definition.script:
pipeline {
    agent any
    stages {
        stage('Checkout') {
            steps {
                git branch: 'feature_julian', url: 'https://github.com/caroandres356-eng/Administrador-de-Compras-de-Mercado.git'
            }
        }
        stage('Build and Test') {
            steps {
                dir('backend') {
                    sh 'docker network create jenkins-net 2>/dev/null || true'
                    sh 'docker rm -f test-mariadb 2>/dev/null || true'
                    sh 'docker run -d --name test-mariadb --network container:jenkins -e MYSQL_ROOT_PASSWORD=Pipesofi2006 -e MYSQL_DATABASE=mercalist_test_db mariadb:11'
                    sh 'for i in $(seq 1 30); do docker exec test-mariadb mariadb-admin ping -uroot -pPipesofi2006 --silent 2>/dev/null && break; sleep 2; done'
                    sh 'mvn clean package'
                }
            }
        }
        stage('Docker Build') {
            steps {
                sh 'docker build -t market-admin:latest ./backend'
            }
        }
        stage('Docker Deploy') {
            steps {
                sh 'docker rm -f deploy-db 2>/dev/null || true'
                sh 'docker run -d --name deploy-db --network jenkins-net -e MYSQL_ROOT_PASSWORD=Pipesofi2006 -e MYSQL_DATABASE=mercalist_db mariadb:11'
                sh 'for i in $(seq 1 30); do docker exec deploy-db mariadb-admin ping -uroot -pPipesofi2006 --silent 2>/dev/null && break; sleep 2; done'
                sh 'docker rm -f market-admin 2>/dev/null || true'
                sh 'docker run -d --name market-admin --network jenkins-net -p 8081:8080 -e DB_HOST=deploy-db -e DB_NAME=mercalist_db -e DB_PASS=Pipesofi2006 -e SPRING_PROFILES_ACTIVE=dev market-admin:latest'
            }
        }
    }
    post {
        always {
            sh 'docker rm -f test-mariadb 2>/dev/null || true'
            echo 'Pipeline terminado.'
        }
        success {
            echo '!Despliegue exitoso!'
        }
        failure {
            echo 'Error en el pipeline. Revisar los logs.'
        }
    }
}
